package com.mfg.crm.controller;import com.mfg.common.api.ApiResponse;import com.mfg.crm.service.CrmP2Service;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/crm") @RequiredArgsConstructor public class CrmP2Controller{private final CrmP2Service s;
 private ApiResponse<Page<Map<String,Object>>>page(String t,String k,String st,int p,int z){return ApiResponse.ok(s.list(t,k,st,p,z));}
 @GetMapping("/leads")public ApiResponse<Page<Map<String,Object>>>leads(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("crm_lead",keyword,status,page,size);}@PostMapping("/leads")public ApiResponse<Map<String,Object>>lead(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createLead(x));}@PostMapping("/leads/{id}/assign")public ApiResponse<Void>assign(@PathVariable long id,@RequestBody Map<String,Object>x){s.assign(id,x);return ApiResponse.ok();}@PostMapping("/leads/{id}/follow")public ApiResponse<Void>follow(@PathVariable long id,@RequestBody Map<String,Object>x){s.follow(id,x);return ApiResponse.ok();}@PostMapping("/leads/{id}/convert")public ApiResponse<Map<String,Object>>convert(@PathVariable long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.convert(id,x));}
 @GetMapping("/quotations")public ApiResponse<Page<Map<String,Object>>>quotes(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("crm_quotation",keyword,status,page,size);}@PostMapping("/quotations")public ApiResponse<Map<String,Object>>quote(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createQuote(x));}@PostMapping("/quotations/{id}/new-version")public ApiResponse<Map<String,Object>>version(@PathVariable long id){return ApiResponse.ok(s.newVersion(id));}@PostMapping("/quotations/{id}/submit")public ApiResponse<?>submitQuote(@PathVariable long id){return ApiResponse.ok(s.submit(id,"QUOTATION"));}@PostMapping("/quotations/{id}/activate")public ApiResponse<Void>activateQuote(@PathVariable long id){s.activateQuote(id);return ApiResponse.ok();}
 @GetMapping("/contracts")public ApiResponse<Page<Map<String,Object>>>contracts(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("crm_contract",keyword,status,page,size);}@PostMapping("/contracts")public ApiResponse<Map<String,Object>>contract(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createContract(x));}@PostMapping("/contracts/{id}/submit")public ApiResponse<?>submitContract(@PathVariable long id){return ApiResponse.ok(s.submit(id,"CONTRACT"));}@PostMapping("/contracts/{id}/activate")public ApiResponse<Void>activate(@PathVariable long id){s.activate(id);return ApiResponse.ok();}@PostMapping("/contracts/{id}/create-order")public ApiResponse<Map<String,Object>>order(@PathVariable long id){return ApiResponse.ok(s.createOrder(id));}@PostMapping("/contracts/{id}/new-version")public ApiResponse<Map<String,Object>>contractVersion(@PathVariable long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.newContractVersion(id,x));}
 @GetMapping("/complaints")public ApiResponse<Page<Map<String,Object>>>complaints(@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return page("crm_complaint",keyword,status,page,size);}@PostMapping("/complaints")public ApiResponse<Map<String,Object>>complaint(@RequestBody Map<String,Object>x){return ApiResponse.ok(s.createComplaint(x));}@GetMapping("/forecast")public ApiResponse<Page<Map<String,Object>>>forecast(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.forecast(page,size));}@GetMapping("/customer-360/{code}")public ApiResponse<Map<String,Object>>customer(@PathVariable String code){return ApiResponse.ok(s.customer360(code));}
}
